        return 1;
    }
    MPI_Init(nullptr, nullptr);
    int g_npu = atoi(argv[1]);
    int pe;
    int pe_size;
    MPI_Comm_rank(MPI_COMM_WORLD, &pe);
    MPI_Comm_size(MPI_COMM_WORLD, &pe_size);
    int status = ACLSHMEM_SUCCESS;

    aclInit(nullptr);
