    int64_t local_mem_size = 1024 * 1024 * 1024;
    if (pe == 0) {
        status = aclshmemx_get_uniqueid(&uid);
    }

    MPI_Bcast(&uid, sizeof(aclshmemx_uniqueid_t), MPI_UINT8_T, 0, MPI_COMM_WORLD);
    status = aclshmemx_set_attr_uniqueid_args(pe, pe_size, 
                                                local_mem_size, 
