        aclrtResetDevice(pe);
        aclFinalize();
        MPI_Finalize();
        return 1;
    }
    std::cout << "pe " << pe << ": shmem init SUCCESS" << std::endl;

    status = shmem_finalize();
    aclrtResetDevice(pe);
    aclFinalize();
    MPI_Finalize();
    if (status != ACLSHMEM_SUCCESS) {
        std::cout << "[ERROR] pe " << pe << ": demo run failed!" << std::endl;
        return 1;
    } else {
